do $$ declare p jsonb; pid uuid;begin for p in select value from jsonb_array_elements($samples$[{"slug":"sample-a-little-box-of-joy","name":"[SAMPLE] A little box of joy","price":89900,"colour":"rose","category":"gift-hampers","occasion":"birthday"},{"slug":"sample-forever-in-bloom","name":"[SAMPLE] Forever in bloom","price":64900,"colour":"cream","category":"flower-bouquets","occasion":"anniversary-couples"},{"slug":"sample-memories-in-a-frame","name":"[SAMPLE] Memories in a frame","price":74900,"colour":"green","category":"photo-frames","occasion":"wedding"},{"slug":"sample-a-little-piece-of-you","name":"[SAMPLE] A little piece of you","price":24900,"colour":"rose","category":"keychains","occasion":"friendship"},{"slug":"sample-the-festive-edit","name":"[SAMPLE] The festive edit","price":129900,"colour":"gold","category":"festive-hampers","occasion":"diwali"},{"slug":"sample-sweet-little-surprises","name":"[SAMPLE] Sweet little surprises","price":49900,"colour":"lavender","category":"gift-hampers","occasion":"just-because"},{"slug":"sample-petals-with-a-twist","name":"[SAMPLE] Petals with a twist","price":59900,"colour":"rose","category":"pipe-cleaner-bouquets","occasion":"birthday"},{"slug":"sample-your-name-your-story","name":"[SAMPLE] Your name, your story","price":99900,"colour":"cream","category":"name-plates","occasion":"wedding"},{"slug":"sample-made-to-be-kept","name":"[SAMPLE] Made to be kept","price":39900,"colour":"lavender","category":"resin-articles","occasion":"return-gifts"},{"slug":"sample-the-thank-you-hamper","name":"[SAMPLE] The thank-you hamper","price":149900,"colour":"green","category":"corporate-bulk-items","occasion":"corporate"}]$samples$::jsonb) loop
insert into memocious.products(slug,name,description,detail,price_paise,colour,customizable,active,publication_state,materials,dimensions) values(p->>'slug',p->>'name','STAGING SAMPLE — illustrative design and price; not inventory.','Generated sample artwork is supplied with the application. Review real materials, pricing, lead time and media before making any genuine offer.',(p->>'price')::bigint,p->>'colour',true,false,'draft','Sample materials, to be confirmed','Sample dimensions, to be confirmed') on conflict(slug) do nothing returning id into pid;
if pid is not null then insert into memocious.product_categories(product_id,category_id) select pid,id from memocious.categories where slug=p->>'category';insert into memocious.product_occasions(product_id,occasion_id) select pid,id from memocious.occasions where slug=p->>'occasion';end if;end loop;end $$;
